import copy
import json
import os
import random
import tomllib
from decimal import Decimal

_HERE = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(_HERE, "data.toml"), "rb") as _f:
    _DATA = tomllib.load(_f)


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


_BLOCKED = object()
_FIELDS = ("day", "cash", "items", "lots", "notes", "armed", "rel", "susp",
           "orders", "next_order", "shipped", "returned", "shipped_by_day",
           "held", "overdrawn")


def _op(f):
    def wrapper(self, *a, **k):
        before = self._snap()
        try:
            r = f(self, *a, **k)
        except BaseException:
            self._restore(before)
            raise
        self._undo = before
        return r
    wrapper.__name__ = f.__name__
    return wrapper


def _qty_ok(q):
    if not isinstance(q, int) or isinstance(q, bool) or q <= 0:
        raise DepotError("INVALID_QTY")


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode,
                 late_penalty_pct=None, return_perishables=None):
        self.warehouses = list(warehouses)
        self.capacities = dict(capacities)
        self.rounding_mode = rounding_mode
        self.late_penalty_pct = late_penalty_pct      # owner decision (C18)
        self.return_perishables = return_perishables  # owner decision (C23)
        self.cfg = _DATA
        self.day_ = 0
        self.day = 0
        self.cash_ = opening_cash
        self.cash = opening_cash
        self.items = {}
        self.lots = {}
        self.notes = []
        self.armed = set()
        self.rel = {}
        self.susp = set()
        self.orders = {}
        self.next_order = 1
        self.shipped = {}
        self.returned = {}
        self.shipped_by_day = {}
        self.held = {}
        self.overdrawn = False
        self._undo = None

    # day / cash as read-only properties backed by private slots
    @property
    def cash(self):
        return self._cash

    @cash.setter
    def cash(self, v):
        self._cash = v

    @property
    def day(self):
        return self._day

    @day.setter
    def day(self, v):
        self._day = v

    # --- state helpers
    def _snap(self):
        return copy.deepcopy({n: getattr(self, n) for n in _FIELDS})

    def _restore(self, s):
        for n, v in copy.deepcopy(s).items():
            setattr(self, n, v)

    def _sku(self, sku):
        if sku not in self.items:
            raise DepotError("UNKNOWN_SKU")

    def _wh(self, wh):
        if wh not in self.warehouses:
            raise DepotError("UNKNOWN_WAREHOUSE")

    def _units(self, sku, wh):
        return sum(q for _, q in self.lots[sku][wh])

    def _wh_total(self, wh):
        return sum(self._units(s, wh) for s in self.items)

    def _round(self, d):
        return int(Decimal(d).quantize(Decimal(1), rounding=self.rounding_mode))

    def _note(self, *t):
        self.notes.append(tuple(t))

    def _cash_check(self):
        if self.cash < 0:
            if not self.overdrawn:
                self.overdrawn = True
                self._note("OVERDRAWN")
        else:
            self.overdrawn = False

    def _rearm(self, sku, wh):
        if self._units(sku, wh) > self.items[sku][1]:
            self.armed.discard((sku, wh))

    def _take(self, sku, wh, qty):
        taken = []
        lots = self.lots[sku][wh]
        need = qty
        while need > 0:
            d, q = lots[0]
            t = min(q, need)
            taken.append([d, t])
            need -= t
            if t == q:
                lots.pop(0)
            else:
                lots[0][1] -= t
        return taken

    def _add_lots(self, sku, wh, new):
        lots = self.lots[sku][wh]
        lots.extend(new)
        lots.sort(key=lambda l: l[0])

    def _receive(self, sku, qty, wh):
        self._sku(sku)
        self._wh(wh)
        _qty_ok(qty)
        if self.cash < 0:
            raise DepotError("OVERDRAWN")
        if self._wh_total(wh) + qty > self.capacities[wh]:
            raise DepotError("CAPACITY")
        cost = self.items[sku][0] * qty
        if self.cash - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self.cash -= cost
        self._add_lots(sku, wh, [[self.day, qty]])
        self._rearm(sku, wh)

    # --- operations
    @_op
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        if sku in self.items:
            raise DepotError("DUPLICATE_SKU")
        if not isinstance(unit_cost, int) or unit_cost <= 0:
            raise DepotError("INVALID_COST")
        if not isinstance(reorder_level, int) or reorder_level < 0:
            raise DepotError("INVALID_REORDER")
        if shelf_life_days is not None and (
                not isinstance(shelf_life_days, int) or shelf_life_days < 1):
            raise DepotError("INVALID_SHELF_LIFE")
        self.items[sku] = (unit_cost, reorder_level, shelf_life_days)
        self.lots[sku] = {w: [] for w in self.warehouses}
        self.shipped[sku] = 0
        self.returned[sku] = 0

    @_op
    def receive(self, sku, qty, wh):
        self._receive(sku, qty, wh)

    @_op
    def receive_bulk(self, receipts):
        for sku, qty, wh in receipts:
            self._receive(sku, qty, wh)

    @_op
    def ship(self, sku, qty, wh, price):
        self._sku(sku)
        self._wh(wh)
        _qty_ok(qty)
        if not isinstance(price, int) or price < 0:
            raise DepotError("INVALID_PRICE")
        if self._units(sku, wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        self._take(sku, wh, qty)
        pct = 0
        if qty >= self.cfg["bulk_threshold"]:
            pct = self.cfg["bulk_discount_pct"]
        self.cash += self._round(Decimal(price * qty * (100 - pct)) / Decimal(100))
        self.shipped[sku] += qty
        self.shipped_by_day[self.day] = self.shipped_by_day.get(self.day, 0) + qty
        self._cash_check()
        if self._units(sku, wh) <= self.items[sku][1]:
            if (sku, wh) not in self.armed:
                self.armed.add((sku, wh))
                self._note("REORDER", sku, wh)
        else:
            self.armed.discard((sku, wh))

    def list_price(self, sku):
        self._sku(sku)
        d = Decimal(self.items[sku][0]) * (1 + Decimal(str(self.cfg["markup"])))
        return self._round(d)

    @_op
    def transfer(self, sku, qty, from_wh, to_wh):
        self._sku(sku)
        self._wh(from_wh)
        self._wh(to_wh)
        _qty_ok(qty)
        if from_wh == to_wh:
            raise DepotError("SAME_WAREHOUSE")
        if self._units(sku, from_wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        if self._wh_total(to_wh) + qty > self.capacities[to_wh]:
            raise DepotError("CAPACITY")
        cost = self.cfg["transfer_credit_cents_per_unit"] * qty
        if self.cash - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self.cash -= cost
        moved = self._take(sku, from_wh, qty)
        self._add_lots(sku, to_wh, moved)
        self._rearm(sku, to_wh)

    def advance_day(self):
        before = self._snap()
        try:
            self.held[self.day] = sum(
                self._units(s, w) for s in self.items for w in self.warehouses)
            self.day += 1
            units = sum(self._units(s, w) for s in self.items
                        for w in self.warehouses)
            self.cash -= self.cfg["storage_cents_per_unit_day"] * units
            for sku in sorted(self.items):
                shelf = self.items[sku][2]
                if shelf is None:
                    continue
                for wh in self.warehouses:
                    lots = self.lots[sku][wh]
                    gone = sum(q for d, q in lots if self.day - d > shelf)
                    if gone:
                        self.lots[sku][wh] = [l for l in lots
                                              if self.day - l[0] <= shelf]
                        self._note("EXPIRY", sku, wh, gone)
            self._cash_check()
        except BaseException:
            self._restore(before)
            raise
        self._undo = _BLOCKED

    def undo(self):
        if self._undo is _BLOCKED:
            raise DepotError("UNDO_BLOCKED")
        if self._undo is None:
            raise DepotError("NOTHING_TO_UNDO")
        s = self._undo
        self._restore(s)
        self._undo = None

    def notifications(self):
        return list(self.notes)

    # --- suppliers
    def _rel_changed(self, sup):
        if self.rel[sup] <= 1 and sup not in self.susp:
            self.susp.add(sup)
            self._note("SUPPLIER_SUSPENDED", sup)

    @_op
    def place_order(self, supplier, sku, qty, due_day):
        self._sku(sku)
        _qty_ok(qty)
        if supplier not in self.rel:
            self.rel[supplier] = 3
        if self.rel[supplier] <= 1:
            raise DepotError("SUPPLIER_SUSPENDED")
        oid = self.next_order
        self.next_order += 1
        self.orders[oid] = {"supplier": supplier, "sku": sku, "qty": qty,
                            "due": due_day, "done": False}
        return oid

    @_op
    def deliver(self, order_id, day):
        o = self.orders.get(order_id)
        if o is None:
            raise DepotError("UNKNOWN_ORDER")
        if o["done"]:
            raise DepotError("ORDER_DONE")
        late = day > o["due"]
        pay = self.items[o["sku"]][0] * o["qty"]
        if late:
            if self.late_penalty_pct is None:
                raise DepotError("LATE_PENALTY_UNDECIDED")
            pay = self._round(Decimal(pay * (100 - self.late_penalty_pct))
                              / Decimal(100))
        if self.cash - pay < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self.cash -= pay
        o["done"] = True
        sup = o["supplier"]
        self.rel[sup] = max(0, min(5, self.rel[sup] + (-1 if late else 1)))
        self._rel_changed(sup)

    @_op
    def reinstate(self, supplier):
        if supplier not in self.rel:
            raise DepotError("UNKNOWN_SUPPLIER")
        self.rel[supplier] = 2
        self.susp.discard(supplier)

    def reliability(self, supplier):
        if supplier not in self.rel:
            raise DepotError("UNKNOWN_SUPPLIER")
        return self.rel[supplier]

    # --- audit / returns / queries
    @_op
    def audit(self, counts):
        if not counts:
            raise DepotError("EMPTY_AUDIT")
        for sku, wh in counts:
            self._sku(sku)
            self._wh(wh)
        for sku, wh in sorted(counts):
            ledger = self._units(sku, wh)
            if ledger != counts[(sku, wh)]:
                self._note("AUDIT_MISMATCH", sku, wh, ledger, counts[(sku, wh)])

    @_op
    def return_goods(self, sku, qty, wh, price):
        self._sku(sku)
        self._wh(wh)
        _qty_ok(qty)
        if not isinstance(price, int) or price < 0:
            raise DepotError("INVALID_PRICE")
        perishable = self.items[sku][2] is not None
        if perishable and self.return_perishables is None:
            raise DepotError("RETURN_POLICY_UNDECIDED")
        if self.returned[sku] + qty > self.shipped[sku]:
            raise DepotError("RETURN_EXCEEDS")
        restock = not (perishable and self.return_perishables == "discard")
        if restock and self._wh_total(wh) + qty > self.capacities[wh]:
            raise DepotError("CAPACITY")
        self.cash -= price * qty
        self.returned[sku] += qty
        if restock:
            self._add_lots(sku, wh, [[self.day, qty]])
            self._rearm(sku, wh)
        self._cash_check()

    def stock(self, sku, wh=None):
        self._sku(sku)
        if wh is None:
            return sum(self._units(sku, w) for w in self.warehouses)
        self._wh(wh)
        return self._units(sku, wh)

    def report(self):
        rows = []
        for sku in sorted(self.items):
            for wh in sorted(self.warehouses):
                u = self._units(sku, wh)
                if u > 0:
                    rows.append((sku, wh, u, u * self.items[sku][0]))
        return rows

    def turnover(self, start_day, end_day):
        if start_day > end_day or start_day < 0 or end_day > self.day:
            raise DepotError("BAD_RANGE")
        days = range(start_day, end_day + 1)
        shipped = sum(self.shipped_by_day.get(d, 0) for d in days)
        cur = sum(self._units(s, w) for s in self.items for w in self.warehouses)
        total = sum(self.held.get(d, cur) if d != self.day else cur for d in days)
        avg = Decimal(total) / Decimal(len(days))
        if avg == 0:
            return None
        return Decimal(shipped) / avg

    # --- persistence
    def save(self):
        d = {
            "version": 1,
            "day": self.day, "cash": self.cash,
            "items": {k: list(v) for k, v in self.items.items()},
            "lots": self.lots,
            "notes": [list(n) for n in self.notes],
            "armed": sorted([list(a) for a in self.armed]),
            "rel": self.rel, "susp": sorted(self.susp),
            "orders": {str(k): v for k, v in self.orders.items()},
            "next_order": self.next_order,
            "shipped": self.shipped, "returned": self.returned,
            "shipped_by_day": {str(k): v for k, v in self.shipped_by_day.items()},
            "held": {str(k): v for k, v in self.held.items()},
            "overdrawn": self.overdrawn,
        }
        return json.dumps(d)

    def load(self, s):
        try:
            d = json.loads(s)
            if not isinstance(d, dict) or d.get("version") != 1:
                raise ValueError
            new = {
                "day": int(d["day"]), "cash": int(d["cash"]),
                "items": {k: tuple(v) for k, v in d["items"].items()},
                "lots": {k: {w: [list(l) for l in ls] for w, ls in m.items()}
                         for k, m in d["lots"].items()},
                "notes": [tuple(n) for n in d["notes"]],
                "armed": {tuple(a) for a in d["armed"]},
                "rel": dict(d["rel"]), "susp": set(d["susp"]),
                "orders": {int(k): dict(v) for k, v in d["orders"].items()},
                "next_order": int(d["next_order"]),
                "shipped": dict(d["shipped"]), "returned": dict(d["returned"]),
                "shipped_by_day": {int(k): int(v)
                                   for k, v in d["shipped_by_day"].items()},
                "held": {int(k): int(v) for k, v in d["held"].items()},
                "overdrawn": bool(d["overdrawn"]),
            }
            for sku in new["items"]:
                if set(new["lots"][sku]) != set(self.warehouses):
                    raise ValueError
                new["shipped"][sku] + new["returned"][sku]
                for ls in new["lots"][sku].values():
                    for l in ls:
                        if len(l) != 2 or not all(isinstance(x, int) for x in l):
                            raise ValueError
        except Exception:
            raise DepotError("BAD_SAVE")
        for n, v in new.items():
            setattr(self, n, v)
        self._undo = None


def simulate(days, seed):
    rng = random.Random(seed)
    demand = _DATA["demand"]
    out = []
    for _ in range(days):
        day = []
        for sku, r in demand.items():
            q = rng.randint(r["min"], r["max"])
            if q > 0:
                day.append((sku, q))
        out.append(day)
    return out
